head.script:
/* =====================================================================
 * CHECK-IN - QUÉT QR (camera, ảnh QR, nhập tay, tìm khách), RECENT SCANS
 * API: /api/checkin (xem API_GUEST.md mục 7)
 * ===================================================================== */
scwin.P = "sc";
/* =====================================================================
 * LỚP DÙNG CHUNG (giống các màn Hội trường / Sự kiện)
 *   - Phiên đăng nhập, quyền
 *   - Gọi API JSON bằng submission WebSquare (scwin.callApi)
 *   - Upload / tải file bằng XMLHttpRequest (submission không xử lý file nhị phân)
 * ===================================================================== */
scwin.API_BASE = "http://localhost:8081";
scwin.KEY = { TOKEN: "ssc_token", USER: "ssc_user", PERMS: "ssc_permissions", MENUS: "ssc_menus" };
scwin.LOGIN_PAGE = "/authPage/LoginPage.xml";
scwin.CTX = window.location.pathname.replace(/\/websquare\/websquare\.html.*$/, "");
scwin.SBM_TIMEOUT = 60000;
scwin.sbmQueue = {};
scwin.sbmJob = {};
scwin.toastTimer = null;

/* ---------- Tiện ích ---------- */
scwin.comp = function (id) { return $p.getComponentById(id); };
scwin.domOf = function (c) { return c ? (c.render || document.getElementById(c.id) || null) : null; };
scwin.show = function (c, v) { if (!c) return; if (v === false) c.addClass("is-hidden"); else c.removeClass("is-hidden"); };
scwin.toggleClass = function (c, cls, on) { if (!c) return; if (on) c.addClass(cls); else c.removeClass(cls); };
scwin.safeColor = function (c) { return /^#[0-9a-f]{3,8}$/i.test(String(c || "")) ? c : "#63746b"; };
scwin.trim = function (v) { return v == null ? "" : String(v).replace(/^\s+|\s+$/g, ""); };
scwin.dash = function (v) { return (v == null || scwin.trim(v) === "") ? "—" : String(v); };
scwin.pad = function (n) { return n < 10 ? "0" + n : String(n); };
scwin.clamp = function (v, a, b) { v = Number(v) || 0; a = a == null ? 0 : a; b = b == null ? 100 : b; return Math.max(a, Math.min(b, v)); };
scwin.hasOwn = function (o, k) { return o != null && Object.prototype.hasOwnProperty.call(o, k); };
scwin.fmtNumber = function (n) { return (n == null || n === "" || isNaN(Number(n))) ? "—" : Number(n).toLocaleString("vi-VN"); };
scwin.fmtRate = function (r) { return (Math.round((Number(r) || 0) * 10) / 10).toLocaleString("vi-VN") + "%"; };
scwin.fmtDate = function (s) { if (!s) return ""; var p = String(s).substring(0, 10).split("-"); return p.length === 3 ? p[2] + "/" + p[1] + "/" + p[0] : String(s); };
scwin.fmtTime = function (s) { return s ? String(s).substring(0, 5) : ""; };
scwin.fmtDateTime = function (iso) {
    if (!iso) return "—";
    var d = new Date(iso);
    if (isNaN(d.getTime())) return String(iso);
    return scwin.pad(d.getDate()) + "/" + scwin.pad(d.getMonth() + 1) + "/" + d.getFullYear() + " " + scwin.pad(d.getHours()) + ":" + scwin.pad(d.getMinutes());
};
scwin.fmtClock = function (iso) {
    var d = iso ? new Date(iso) : new Date();
    if (isNaN(d.getTime())) d = new Date();
    return scwin.pad(d.getHours()) + ":" + scwin.pad(d.getMinutes()) + ":" + scwin.pad(d.getSeconds());
};
scwin.fmtSize = function (b) { return b >= 1048576 ? (b / 1048576).toFixed(1) + " MB" : Math.max(1, Math.round(b / 1024)) + " KB"; };
/** Tham số mảng được nối bằng dấu phẩy (backend nhận cả "A,B" lẫn lặp tham số). */
scwin.buildQuery = function (p) {
    var out = [];
    for (var k in p) {
        if (!p.hasOwnProperty(k)) continue;
        var v = p[k];
        if (Array.isArray(v)) { if (!v.length) continue; v = v.join(","); }
        if (v === null || v === undefined || v === "") continue;
        out.push(encodeURIComponent(k) + "=" + encodeURIComponent(v));
    }
    return out.join("&");
};
scwin.getQueryParam = function (name) {
    var m = new RegExp("[?&]" + name + "=([^&#]*)").exec(window.location.search);
    return m ? decodeURIComponent(m[1].replace(/\+/g, " ")) : "";
};
scwin.pageUrl = function (path, params) {
    var q = params ? scwin.buildQuery(params) : "";
    return scwin.CTX + "/websquare/websquare.html?w2xPath=" + scwin.CTX + path + (q ? "&" + q : "");
};
scwin.escHtml = function (s) { return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;"); };
scwin.el = function (tag, cls, text) { var e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; };
scwin.clearEl = function (el) { if (el) while (el.firstChild) el.removeChild(el.firstChild); };
scwin.fitGrid = function (grid, rows, rowH, maxRows) {
    var n = maxRows ? Math.min(rows, maxRows) : rows;
    grid.setStyle("height", (rows ? 42 + n * (rowH || 46) + 2 : 0) + "px");
    scwin.show(grid, rows > 0);
};
scwin.isTrue = function (v) { return v === true || v === "true" || v === 1 || v === "1"; };

/* ---------- Phiên đăng nhập & quyền ---------- */
scwin.storeGet = function (k) { try { return window.localStorage.getItem(k) || window.sessionStorage.getItem(k) || ""; } catch (e) { return ""; } };
scwin.parseJSON = function (t) { if (!t || typeof t !== "string") return null; try { return JSON.parse(t); } catch (e) { return null; } };
scwin.getToken = function () { return String(scwin.storeGet(scwin.KEY.TOKEN)).replace(/^Bearer\s+/i, ""); };
scwin.getPerms = function () { return scwin.parseJSON(scwin.storeGet(scwin.KEY.PERMS)) || []; };
scwin.getUser = function () { return scwin.parseJSON(scwin.storeGet(scwin.KEY.USER)) || {}; };
/** Header chưa kịp lưu quyền (lần đầu vào trang) thì tạm cho phép; backend vẫn chặn bằng 403. */
scwin.can = function (code) { var p = scwin.getPerms(); return !p.length || p.indexOf(code) >= 0; };
scwin.canAny = function (codes) { for (var i = 0; i < codes.length; i++) if (scwin.can(codes[i])) return true; return false; };
scwin.goLogin = function () {
    if (scwin._redirecting) return;
    scwin._redirecting = true;
    for (var k in scwin.KEY) {
        if (!scwin.KEY.hasOwnProperty(k)) continue;
        try { window.localStorage.removeItem(scwin.KEY[k]); window.sessionStorage.removeItem(scwin.KEY[k]); } catch (e) { }
    }
    window.location.href = scwin.pageUrl(scwin.LOGIN_PAGE);
};

/* ---------- Lỗi ---------- */
scwin.defaultMessage = function (status) {
    if (status === 0) return "Không kết nối được máy chủ. Kiểm tra mạng hoặc backend (" + scwin.API_BASE + ").";
    if (status === 401) return "Phiên đăng nhập đã hết hạn. Hãy đăng nhập lại.";
    if (status === 403) return "Tài khoản của bạn chưa được cấp quyền cho thao tác này.";
    if (status === 404) return "Không tìm thấy dữ liệu, hoặc dữ liệu nằm ngoài phạm vi bạn được xem.";
    if (status >= 500) return "Máy chủ đang gặp sự cố. Thử lại sau ít phút.";
    return "Yêu cầu không thành công (HTTP " + status + ").";
};
scwin.authHeader = function (accept) {
    var h = { "Accept": accept || "application/json" };
    var t = scwin.getToken();
    if (t) h["Authorization"] = "Bearer " + t;
    return h;
};
/** Chuẩn hóa lỗi: { status, code, message, data }. 401 thì đưa về trang đăng nhập. */
scwin.buildError = function (status, json) {
    var err = {
        status: status || 0,
        code: (json && json.code) || (status ? "HTTP_" + status : "NETWORK_ERROR"),
        message: (json && json.message) || scwin.defaultMessage(status || 0),
        data: json ? json.data : null
    };
    if (status === 401) {
        err.message = scwin.defaultMessage(401);
        scwin.toast(err.message + " Đang chuyển về trang đăng nhập…", "error");
        setTimeout(scwin.goLogin, 1500);
    }
    return err;
};

/* ---------- Submission ----------
 *   scwin.callApi("sbm_xxx", { url: "...", body: {...} }) -> Promise<data>
 *   Mỗi submission có hàng đợi riêng nên gọi chồng nhau không bị trả nhầm kết quả.
 */
scwin.callApi = function (sbmId, opts) {
    return new Promise(function (resolve, reject) {
        if (!scwin.sbmQueue[sbmId]) scwin.sbmQueue[sbmId] = [];
        scwin.sbmQueue[sbmId].push({ opts: opts || {}, resolve: resolve, reject: reject });
        scwin.sbmNext(sbmId);
    });
};
scwin.sbmNext = function (sbmId) {
    if (scwin.sbmJob[sbmId]) return;
    var q = scwin.sbmQueue[sbmId];
    if (!q || !q.length) return;
    var job = q.shift();
    scwin.sbmJob[sbmId] = job;
    var sbm = $p.getSubmission(sbmId);
    if (!sbm) { scwin.sbmSettle(sbmId, null, { status: 0, code: "SUBMISSION_NOT_FOUND", message: "Chưa khai báo submission " + sbmId + "." }); return; }
    sbm.action = job.opts.url;
    sbm.requestHeader = scwin.authHeader();
    job.timer = setTimeout(function () {
        scwin.sbmSettle(sbmId, null, { status: 0, code: "TIMEOUT", message: "Máy chủ phản hồi quá lâu. Thử lại sau." });
    }, scwin.SBM_TIMEOUT);
    try {
        if (job.opts.body !== undefined) $p.executeSubmission(sbmId, job.opts.body);
        else $p.executeSubmission(sbmId);
    } catch (ex) {
        scwin.sbmSettle(sbmId, null, { status: 0, code: "SUBMISSION_ERROR", message: (ex && ex.message) || String(ex) });
    }
};
scwin.sbmSettle = function (sbmId, data, err) {
    var job = scwin.sbmJob[sbmId];
    if (!job) return;
    clearTimeout(job.timer);
    scwin.sbmJob[sbmId] = null;
    if (err) job.reject(err); else job.resolve(data);
    scwin.sbmNext(sbmId);
};
scwin.readResponse = function (e) {
    if (!e) return null;
    if (e.responseJSON && typeof e.responseJSON === "object") return e.responseJSON;
    return scwin.parseJSON(e.responseText) || scwin.parseJSON(e.responseBody);
};
scwin.onSbmDone = function (sbmId, e) {
    var json = scwin.readResponse(e);
    if (json && json.success === false) { scwin.sbmSettle(sbmId, null, scwin.buildError((e && e.responseStatusCode) || 200, json)); return; }
    scwin.sbmSettle(sbmId, scwin.hasOwn(json, "data") ? json.data : json, null);
};
scwin.onSbmError = function (sbmId, e) {
    var status = (e && (e.responseStatusCode || e.status)) || 0;
    scwin.sbmSettle(sbmId, null, scwin.buildError(status, scwin.readResponse(e)));
};

/* ---------- XMLHttpRequest: upload multipart, nhận file ----------
 *   opts.body: object (gửi JSON) | FormData (multipart)
 *   opts.responseType: "json" (mặc định) | "blob" -> resolve { blob, name, type, headers }
 */
scwin.xhr = function (method, url, opts) {
    opts = opts || {};
    return new Promise(function (resolve, reject) {
        var x = new XMLHttpRequest();
        x.open(method, url);
        var h = scwin.authHeader(opts.responseType === "blob" ? "*/*" : "application/json");
        for (var k in h) if (h.hasOwnProperty(k)) x.setRequestHeader(k, h[k]);
        var body = null;
        if (typeof FormData !== "undefined" && opts.body instanceof FormData) body = opts.body;
        else if (opts.body !== undefined && opts.body !== null) { x.setRequestHeader("Content-Type", "application/json"); body = JSON.stringify(opts.body); }
        if (opts.responseType === "blob") x.responseType = "blob";
        if (opts.onProgress && x.upload) x.upload.onprogress = function (ev) { if (ev.lengthComputable) opts.onProgress(Math.round(ev.loaded * 100 / ev.total)); };
        x.onload = function () {
            var ok = x.status >= 200 && x.status < 300;
            if (opts.responseType === "blob") {
                var type = x.getResponseHeader("Content-Type") || "";
                if (ok && type.indexOf("application/json") < 0) {
                    resolve({ blob: x.response, type: type, name: scwin.fileNameFrom(x.getResponseHeader("Content-Disposition")), xhr: x });
                    return;
                }
                scwin.readBlobJSON(x.response).then(function (json) { reject(scwin.buildError(ok ? 200 : x.status, json)); });
                return;
            }
            var json = scwin.parseJSON(x.responseText);
            if (ok && !(json && json.success === false)) resolve(scwin.hasOwn(json, "data") ? json.data : json);
            else reject(scwin.buildError(x.status, json));
        };
        x.onerror = function () { reject(scwin.buildError(0, null)); };
        x.send(body);
    });
};
scwin.readBlobJSON = function (blob) {
    return new Promise(function (resolve) {
        if (!blob || typeof FileReader === "undefined") { resolve(null); return; }
        var r = new FileReader();
        r.onload = function () { resolve(scwin.parseJSON(r.result)); };
        r.onerror = function () { resolve(null); };
        r.readAsText(blob);
    });
};
scwin.fileNameFrom = function (cd) {
    if (!cd) return "";
    var m = /filename\*=UTF-8''([^;]+)/i.exec(cd) || /filename="?([^";]+)"?/i.exec(cd);
    if (!m) return "";
    try { return decodeURIComponent(m[1]); } catch (e) { return m[1]; }
};
scwin.saveBlob = function (blob, name) {
    var url = URL.createObjectURL(blob);
    var a = scwin.el("a", scwin.P + "-native-link");
    a.href = url; a.download = name;
    document.body.appendChild(a); a.click();
    setTimeout(function () { URL.revokeObjectURL(url); if (a.parentNode) a.parentNode.removeChild(a); }, 1500);
};
/** Tải file (GET hoặc POST kèm body JSON) rồi lưu về máy. */
scwin.downloadFile = function (url, fallbackName, btn, method, body) {
    if (btn) btn.addClass("is-busy");
    return scwin.xhr(method || "GET", url, { responseType: "blob", body: body }).then(function (r) {
        scwin.saveBlob(r.blob, r.name || fallbackName);
        return r;
    }).catch(function (err) {
        scwin.toast(err.message, "error");
        throw err;
    }).then(function (r) { if (btn) btn.removeClass("is-busy"); return r; }, function () { if (btn) btn.removeClass("is-busy"); });
};
/** In file PDF: nạp vào iframe ẩn rồi mở hộp thoại in của trình duyệt. */
scwin.printBlob = function (blob) {
    return new Promise(function (resolve) {
        var old = document.getElementById("ssc-print-frame");
        if (old) old.parentNode.removeChild(old);
        var url = URL.createObjectURL(blob);
        var f = document.createElement("iframe");
        f.id = "ssc-print-frame";
        f.className = scwin.P + "-print-frame";
        f.src = url;
        f.onload = function () {
            setTimeout(function () {
                try { f.contentWindow.focus(); f.contentWindow.print(); }
                catch (e) { window.open(url, "_blank"); }
                resolve();
            }, 300);
        };
        document.body.appendChild(f);
    });
};

/* ---------- Thông báo ---------- */
scwin.toast = function (msg, type) {
    if (typeof tbx_toast === "undefined") return;
    clearTimeout(scwin.toastTimer);
    tbx_toast.setValue(msg || "");
    ["success", "error", "warning", "info"].forEach(function (c) { tbx_toast.removeClass(scwin.P + "-toast--" + c); });
    tbx_toast.addClass(scwin.P + "-toast--" + (type || "info"));
    tbx_toast.addClass("is-show");
    scwin.toastTimer = setTimeout(function () { tbx_toast.removeClass("is-show"); }, (type === "error" || type === "warning") ? 6500 : 3800);
};
scwin.tbx_toast_onclick = function () { tbx_toast.removeClass("is-show"); };
scwin.showWarnings = function (list) {
    if (!list || !list.length) return;
    setTimeout(function () { scwin.toast("Lưu ý: " + list.join(" "), "warning"); }, 1800);
};

/* ---------- Danh mục dùng chung: GET /api/guests/lookups ---------- */
scwin.lookups = { events: [], guestTypes: [], guestStatuses: [] };
scwin.typeMeta = function (code) {
    for (var i = 0; i < scwin.lookups.guestTypes.length; i++) if (scwin.lookups.guestTypes[i].code === code) return scwin.lookups.guestTypes[i];
    return { code: code, name: code || "—", color: "#9E9E9E" };
};
scwin.statusMeta = function (code) {
    for (var i = 0; i < scwin.lookups.guestStatuses.length; i++) if (scwin.lookups.guestStatuses[i].code === code) return scwin.lookups.guestStatuses[i];
    return { code: code, name: code || "—", color: "#9E9E9E" };
};
scwin.GUEST_TYPE_VN = { VIP: "VIP", SPEAKER: "Diễn giả", GUEST: "Khách mời", STAFF: "Nhân viên", PRESS: "Báo chí", OTHER: "Khác" };
scwin.GUEST_STATUS_VN = { INVITED: "Đã mời", CONFIRMED: "Đã xác nhận", CHECKED_IN: "Đã check-in", ABSENT: "Vắng mặt" };
scwin.typeName = function (code) { return scwin.GUEST_TYPE_VN[code] || scwin.typeMeta(code).name; };
scwin.statusName = function (code) { return scwin.GUEST_STATUS_VN[code] || scwin.statusMeta(code).name; };
scwin.eventLabel = function (e) { return e.eventCode + " - " + e.eventName + (e.startDate ? " (" + scwin.fmtDate(e.startDate) + ")" : ""); };


scwin.GUEST_API = scwin.API_BASE + "/api/guests";
scwin.CHECKIN_API = scwin.API_BASE + "/api/checkin";
scwin.EVENT_API = scwin.API_BASE + "/api/events";
scwin.PRINT_API = scwin.API_BASE + "/api/print";
scwin.PREF_KEY = "ssc_scan_prefs";
scwin.JSQR_URL = "https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.js";   // dự phòng khi trình duyệt chưa có BarcodeDetector
scwin.DEDUP_MS = 3000;        // bỏ qua cùng một mã nếu vừa quét trong 3 giây
scwin.LOG_REFRESH_MS = 15000; // tự làm mới recent scans (các quầy khác cùng quét)
scwin.RESULT_UI = {
    SUCCESS:            { kind: "ok",   title: "Check-in thành công" },
    ALREADY_CHECKED_IN: { kind: "warn", title: "Khách đã check-in trước đó" },
    INVALID_QR:         { kind: "err",  title: "Mã QR không hợp lệ" },
    WRONG_EVENT:        { kind: "err",  title: "Mã QR của sự kiện khác" },
    GUEST_NOT_FOUND:    { kind: "err",  title: "Không tìm thấy khách" },
    EVENT_NOT_ACTIVE:   { kind: "err",  title: "Sự kiện chưa mở check-in" }
};
scwin.RESULT_VN = { SUCCESS: "Thành công", ALREADY_CHECKED_IN: "Đã check-in", INVALID_QR: "QR không hợp lệ", WRONG_EVENT: "Sai sự kiện", GUEST_NOT_FOUND: "Không có khách", EVENT_NOT_ACTIVE: "Sự kiện chưa mở" };
scwin.METHOD_VN = { QR_CAMERA: "Camera", QR_UPLOAD: "Ảnh QR", MANUAL: "Thủ công" };

scwin.prefs = { eventId: "", device: "", sound: true, vibrate: true, autoPrint: false, mode: "camera" };
scwin.cam = { stream: null, video: null, canvas: null, timer: null, detector: null, decode: null, running: false };
scwin.busy = false;
scwin.last = { text: "", at: 0 };
scwin.event = null;
scwin.wedge = { buf: "", at: 0 };
scwin.timers = {};

/* ---------- Vòng đời ---------- */
scwin.onpageload = function () {
    if (!scwin.getToken()) { scwin.goLogin(); return; }
    var saved = scwin.parseJSON((function () { try { return window.localStorage.getItem(scwin.PREF_KEY); } catch (e) { return ""; } })()) || {};
    for (var k in saved) if (saved.hasOwnProperty(k)) scwin.prefs[k] = saved[k];
    var urlEvent = scwin.getQueryParam("eventId");
    if (urlEvent) scwin.prefs.eventId = urlEvent;
    dma_scan.setJSON({ eventId: scwin.prefs.eventId || "", device: scwin.prefs.device || "", manualCode: "", keyword: "", note: "", logResult: "" });
    scwin.applyToggles();
    scwin.setMode(scwin.prefs.mode || "camera");
    scwin.initUpload();
    scwin.keyHandler = function (e) { scwin.onGlobalKeydown(e); };
    document.addEventListener("keydown", scwin.keyHandler);
    scwin.visHandler = function () { if (document.hidden) scwin.stopCamera(); };
    document.addEventListener("visibilitychange", scwin.visHandler);
    scwin.timers.logs = setInterval(function () { if (!document.hidden && dma_scan.get("eventId")) scwin.loadLogs(true); }, scwin.LOG_REFRESH_MS);
    scwin.resetResult();
    scwin.show(btn_resPrint, false);
    scwin.loadLookups();
};
scwin.onpageunload = function () {
    scwin.stopCamera();
    clearInterval(scwin.timers.logs);
    document.removeEventListener("keydown", scwin.keyHandler);
    document.removeEventListener("visibilitychange", scwin.visHandler);
};

scwin.savePrefs = function () { try { window.localStorage.setItem(scwin.PREF_KEY, JSON.stringify(scwin.prefs)); } catch (e) { } };

scwin.loadLookups = function () {
    scwin.callApi("sbm_lookups", { url: scwin.GUEST_API + "/lookups" }).then(function (d) {
        var events = ((d && d.events) || []).slice();
        // Sự kiện đang diễn ra lên đầu
        events.sort(function (a, b) { return (b.statusCode === "ACTIVE") - (a.statusCode === "ACTIVE"); });
        scwin.lookups.events = events;
        scwin.lookups.guestTypes = (d && d.guestTypes) || [];
        dlt_events.setJSON(events.map(function (e) {
            return { eventId: String(e.eventId), label: (e.statusCode === "ACTIVE" ? "● " : "") + scwin.eventLabel(e) };
        }));
        var id = dma_scan.get("eventId");
        if (!id || !events.some(function (e) { return String(e.eventId) === String(id); })) {
            var act = events.filter(function (e) { return e.statusCode === "ACTIVE"; });
            id = act.length === 1 ? String(act[0].eventId) : "";
        }
        dma_scan.set("eventId", id);
        sbx_event.setValue(id);
        scwin.onEventChanged();
    }).catch(function (err) { scwin.toast("Không tải được danh sách sự kiện: " + err.message, "error"); });
};

/* =====================================================================
 * SỰ KIỆN ĐANG CHECK-IN
 * ===================================================================== */
scwin.sbx_event_onchange = function () { dma_scan.set("eventId", sbx_event.getValue() || ""); scwin.onEventChanged(); };
scwin.onEventChanged = function () {
    var id = dma_scan.get("eventId");
    scwin.prefs.eventId = id;
    scwin.savePrefs();
    scwin.resetResult();
    dlt_found.setJSON([]); scwin.fitGrid(grd_found, 0);
    var ev = scwin.lookups.events.filter(function (e) { return String(e.eventId) === String(id); })[0] || null;
    scwin.event = ev;
    if (!id) {
        tbx_eventWarn.setValue("Chọn sự kiện đang check-in để bắt đầu quét.");
        scwin.show(tbx_eventWarn, true);
        scwin.renderStats(null);
        dlt_logs.setJSON([]); scwin.fitGrid(grd_logs, 0); scwin.show(grp_logsEmpty, true);
        return;
    }
    var notActive = ev && ev.statusCode !== "ACTIVE";
    tbx_eventWarn.setValue(notActive ? "Sự kiện chưa ở trạng thái Đang diễn ra nên quét QR sẽ bị từ chối. Hãy chuyển sự kiện sang Active ở màn Sự kiện." : "");
    scwin.show(tbx_eventWarn, !!notActive);
    scwin.loadEventInfo();
    scwin.loadLogs(false);
};
scwin.loadEventInfo = function () {
    var id = dma_scan.get("eventId");
    scwin.callApi("sbm_eventInfo", { url: scwin.EVENT_API + "/" + id }).then(function (d) {
        if (dma_scan.get("eventId") !== id) return;
        var s = (d && d.checkInSummary) || {};
        scwin.renderStats({ totalGuests: s.totalGuests, checkedInCount: s.checkedInCount, checkInRate: s.checkInRate });
    }).catch(function () { scwin.renderStats(null); });
};
scwin.renderStats = function (s) {
    if (!s) { tbx_statCount.setValue("—"); tbx_statRate.setValue(""); grp_statBar.setStyle("width", "0%"); return; }
    var total = Number(s.totalGuests) || 0, done = Number(s.checkedInCount) || 0;
    var rate = s.checkInRate != null ? Number(s.checkInRate) : (total ? done * 100 / total : 0);
    tbx_statCount.setValue(scwin.fmtNumber(done) + " / " + scwin.fmtNumber(total));
    tbx_statRate.setValue(scwin.fmtRate(rate));
    grp_statBar.setStyle("width", scwin.clamp(rate) + "%");
};

/* ---------- Thiết bị & tùy chọn ---------- */
scwin.ibx_device_onblur = function () {
    scwin.prefs.device = scwin.trim(ibx_device.getValue());
    dma_scan.set("device", scwin.prefs.device);
    scwin.savePrefs();
};
scwin.applyToggles = function () {
    scwin.toggleClass(btn_sound, "is-on", !!scwin.prefs.sound);
    scwin.toggleClass(btn_vibrate, "is-on", !!scwin.prefs.vibrate);
    scwin.toggleClass(btn_autoPrint, "is-on", !!scwin.prefs.autoPrint);
    scwin.show(btn_autoPrint, scwin.can("PRINT_BADGE"));
};
scwin.btn_sound_onclick = function () { scwin.prefs.sound = !scwin.prefs.sound; scwin.applyToggles(); scwin.savePrefs(); if (scwin.prefs.sound) scwin.beep("ok"); };
scwin.btn_vibrate_onclick = function () { scwin.prefs.vibrate = !scwin.prefs.vibrate; scwin.applyToggles(); scwin.savePrefs(); };
scwin.btn_autoPrint_onclick = function () {
    scwin.prefs.autoPrint = !scwin.prefs.autoPrint; scwin.applyToggles(); scwin.savePrefs();
    scwin.toast(scwin.prefs.autoPrint ? "Đã bật tự in thẻ tên sau khi check-in thành công." : "Đã tắt tự in thẻ tên.", "info");
};
scwin.btn_fullscreen_onclick = function () {
    var d = document, el = d.documentElement;
    if (d.fullscreenElement) { if (d.exitFullscreen) d.exitFullscreen(); }
    else if (el.requestFullscreen) el.requestFullscreen().catch(function () { });
};

/* =====================================================================
 * CHẾ ĐỘ QUÉT
 * ===================================================================== */
scwin.MODES = { camera: ["btn_modeCamera", "grp_pCamera"], upload: ["btn_modeUpload", "grp_pUpload"], manual: ["btn_modeManual", "grp_pManual"] };
scwin.setMode = function (m) {
    if (!scwin.MODES[m]) m = "camera";
    scwin.prefs.mode = m; scwin.savePrefs();
    for (var k in scwin.MODES) {
        if (!scwin.MODES.hasOwnProperty(k)) continue;
        scwin.toggleClass(scwin.comp(scwin.MODES[k][0]), "is-selected", k === m);
        scwin.show(scwin.comp(scwin.MODES[k][1]), k === m);
    }
    if (m !== "camera") scwin.stopCamera();
    if (m === "manual") setTimeout(function () { try { ibx_manualCode.focus(); } catch (e) { } }, 80);
};
scwin.btn_modeCamera_onclick = function () { scwin.setMode("camera"); };
scwin.btn_modeUpload_onclick = function () { scwin.setMode("upload"); };
scwin.btn_modeManual_onclick = function () { scwin.setMode("manual"); };

/* ---------- Camera ---------- */
scwin.loadScript = function (url, globalName) {
    return new Promise(function (resolve, reject) {
        if (window[globalName]) { resolve(window[globalName]); return; }
        var s = document.createElement("script");
        s.src = url; s.async = true;
        s.onload = function () { window[globalName] ? resolve(window[globalName]) : reject(new Error("Không nạp được thư viện đọc QR.")); };
        s.onerror = function () { reject(new Error("Không tải được thư viện đọc QR (cần Internet lần đầu).")); };
        document.head.appendChild(s);
    });
};
/** Chọn bộ đọc QR: BarcodeDetector có sẵn của trình duyệt, nếu không có thì dùng jsQR. */
scwin.ensureDecoder = function () {
    if (scwin.cam.decode) return Promise.resolve();
    var tryNative = (window.BarcodeDetector && BarcodeDetector.getSupportedFormats)
        ? BarcodeDetector.getSupportedFormats().then(function (f) { return f.indexOf("qr_code") >= 0; }).catch(function () { return false; })
        : Promise.resolve(false);
    return tryNative.then(function (ok) {
        if (ok) {
            var det = new BarcodeDetector({ formats: ["qr_code"] });
            scwin.cam.decode = function (video) { return det.detect(video).then(function (c) { return c && c.length ? c[0].rawValue : ""; }); };
            return;
        }
        return scwin.loadScript(scwin.JSQR_URL, "jsQR").then(function (jsQR) {
            scwin.cam.canvas = document.createElement("canvas");
            var ctx = scwin.cam.canvas.getContext("2d", { willReadFrequently: true });
            scwin.cam.decode = function (video) {
                var w = video.videoWidth, h = video.videoHeight;
                if (!w || !h) return Promise.resolve("");
                var scale = Math.min(1, 720 / w);
                var cw = Math.round(w * scale), ch = Math.round(h * scale);
                scwin.cam.canvas.width = cw; scwin.cam.canvas.height = ch;
                ctx.drawImage(video, 0, 0, cw, ch);
                var code = jsQR(ctx.getImageData(0, 0, cw, ch).data, cw, ch, { inversionAttempts: "dontInvert" });
                return Promise.resolve(code ? code.data : "");
            };
        });
    });
};

scwin.btn_camStart_onclick = function () { scwin.startCamera(); };
scwin.btn_camStop_onclick = function () { scwin.stopCamera(); };
scwin.startCamera = function (deviceId) {
    scwin.show(tbx_camErr, false);
    if (!dma_scan.get("eventId")) { scwin.toast("Chọn sự kiện trước khi quét.", "warning"); return; }
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        scwin.camError("Trình duyệt không mở được camera. Trang cần chạy trên HTTPS hoặc localhost. Bạn vẫn có thể dùng chế độ Ảnh QR hoặc Nhập tay.");
        return;
    }
    scwin.stopCamera();
    btn_camStart.addClass("is-busy");
    var video = { facingMode: "environment", width: { ideal: 1280 }, height: { ideal: 720 } };
    if (deviceId) video = { deviceId: { exact: deviceId } };
    scwin.ensureDecoder().then(function () {
        return navigator.mediaDevices.getUserMedia({ video: video, audio: false });
    }).then(function (stream) {
        scwin.cam.stream = stream;
        var host = scwin.domOf(grp_camVideo);
        var v = scwin.cam.video;
        if (!v) {
            v = document.createElement("video");
            v.className = "sc-video";
            v.setAttribute("playsinline", "true");
            v.muted = true;
            host.appendChild(v);
            scwin.cam.video = v;
        }
        v.srcObject = stream;
        return v.play();
    }).then(function () {
        scwin.cam.running = true;
        grp_camView.addClass("is-live");
        scwin.show(btn_camStart, false); scwin.show(btn_camStop, true);
        tbx_camHint.setValue("Đưa mã QR vào giữa khung");
        scwin.listCameras();
        scwin.scanLoop();
    }).catch(function (err) {
        var msg = err && err.name === "NotAllowedError" ? "Bạn chưa cho phép dùng camera. Bấm biểu tượng ổ khóa trên thanh địa chỉ để cấp quyền."
            : err && err.name === "NotFoundError" ? "Không tìm thấy camera trên thiết bị."
            : (err && err.message) || "Không mở được camera.";
        scwin.camError(msg);
    }).then(function () { btn_camStart.removeClass("is-busy"); });
};
scwin.camError = function (msg) { tbx_camErr.setValue(msg); scwin.show(tbx_camErr, true); };
scwin.stopCamera = function () {
    var c = scwin.cam;
    clearTimeout(c.timer);
    c.running = false;
    if (c.stream) { c.stream.getTracks().forEach(function (t) { t.stop(); }); c.stream = null; }
    if (c.video) c.video.srcObject = null;
    if (typeof grp_camView !== "undefined") {
        grp_camView.removeClass("is-live");
        scwin.show(btn_camStart, true); scwin.show(btn_camStop, false);
        tbx_camHint.setValue("Bấm Bật camera để bắt đầu quét");
    }
};
scwin.scanLoop = function () {
    var c = scwin.cam;
    if (!c.running) return;
    var next = function () { c.timer = setTimeout(scwin.scanLoop, 160); };
    if (scwin.busy || !c.video || c.video.readyState < 2) { next(); return; }
    c.decode(c.video).then(function (text) { if (text) scwin.onDecoded(text, "QR_CAMERA"); }).catch(function () { }).then(next);
};
scwin.listCameras = function () {
    if (!navigator.mediaDevices.enumerateDevices) return;
    navigator.mediaDevices.enumerateDevices().then(function (list) {
        var cams = list.filter(function (d) { return d.kind === "videoinput"; });
        dlt_cameras.setJSON(cams.map(function (d, i) { return { deviceId: d.deviceId, label: d.label || "Camera " + (i + 1) }; }));
        scwin.show(sbx_camera, cams.length > 1);
        var track = scwin.cam.stream && scwin.cam.stream.getVideoTracks()[0];
        var cur = track && track.getSettings ? track.getSettings().deviceId : "";
        if (cur) sbx_camera.setValue(cur);
    });
};
scwin.sbx_camera_onchange = function () { var id = sbx_camera.getValue(); if (id) scwin.startCamera(id); };

/** Bỏ qua cùng một nội dung QR nếu vừa quét trong 3 giây (camera đọc liên tục). */
scwin.onDecoded = function (text, method) {
    var now = Date.now();
    if (text === scwin.last.text && now - scwin.last.at < scwin.DEDUP_MS) return;
    scwin.last = { text: text, at: now };
    grp_camView.addClass("is-hit");
    setTimeout(function () { grp_camView.removeClass("is-hit"); }, 500);
    scwin.submitScan(text, method);
};

/* =====================================================================
 * GỬI LÊN SERVER & HIỂN THỊ KẾT QUẢ
 * ===================================================================== */
scwin.deviceInfo = function () { return scwin.trim(ibx_device.getValue()) || scwin.prefs.device || navigator.platform || ""; };

scwin.submitScan = function (qrData, method) {
    var eventId = dma_scan.get("eventId");
    if (!eventId) { scwin.toast("Chọn sự kiện trước khi quét.", "warning"); return Promise.resolve(); }
    if (scwin.busy) return Promise.resolve();
    scwin.busy = true;
    grp_result.addClass("is-loading");
    var body = { eventId: Number(eventId), qrData: qrData, deviceInfo: scwin.deviceInfo() };
    if (method) body.method = method;
    return scwin.callApi("sbm_scan", { url: scwin.CHECKIN_API + "/scan", body: body })
        .then(scwin.handleResult, scwin.handleScanError)
        .then(function () { scwin.busy = false; grp_result.removeClass("is-loading"); });
};

/** Kết quả quét luôn HTTP 200: thất bại nằm ở success=false + data.result. */
scwin.handleScanError = function (err) {
    if (err && err.data && err.data.result) { scwin.handleResult(err.data); return; }
    scwin.feedback("err");
    scwin.renderResult({ result: "ERROR", message: err.message }, { kind: "err", title: "Không gửi được yêu cầu" });
};

scwin.handleResult = function (d) {
    var ui = scwin.RESULT_UI[d.result] || { kind: d.success ? "ok" : "err", title: d.message || "Kết quả" };
    scwin.feedback(ui.kind);
    scwin.renderResult(d, ui);
    if (d.eventSummary) scwin.renderStats(d.eventSummary);
    scwin.loadLogs(true);
    // Tự in thẻ tên sau khi check-in thành công
    var ap = d.autoPrint;
    if (scwin.prefs.autoPrint && d.result === "SUCCESS" && d.guest && scwin.can("PRINT_BADGE") && !(ap && ap.alreadyPrinted)) {
        scwin.printBadge(d.guest.guestId, d.guest.fullName, true);
    }
};

scwin.renderResult = function (d, ui) {
    var g = d.guest;
    ["ok", "warn", "err"].forEach(function (k) { scwin.toggleClass(grp_result, "is-" + k, k === ui.kind); });
    grp_result.removeClass("is-idle");
    grp_result.removeClass("is-stale");
    tbx_resTitle.setValue(ui.title);
    tbx_resMsg.setValue(d.message || "");
    tbx_resTime.setValue(d.scannedAt ? "Lúc " + scwin.fmtClock(d.scannedAt) + (d.method ? ", " + (scwin.METHOD_VN[d.method] || d.method) : "") : "");

    scwin.show(grp_resGuest, !!g);
    if (g) {
        var t = scwin.typeMeta(g.guestTypeCode);
        tbx_resName.setValue(g.fullName || "");
        tbx_resType.setValue(scwin.typeName(g.guestTypeCode));
        var tEl = scwin.domOf(tbx_resType);
        if (tEl) tEl.style.setProperty("--sc-type", scwin.safeColor(g.guestTypeColor || t.color));
        tbx_resCompany.setValue([g.position, g.company].filter(function (x) { return !!x; }).join(", "));
        scwin.show(tbx_resCompany, !!(g.position || g.company));
        tbx_resTable.setValue(g.tableNumber ? g.tableNumber : "—");
        scwin.toggleClass(grp_resTableBox, "is-empty", !g.tableNumber);
        tbx_resNotes.setValue(g.notes || "");
        scwin.show(tbx_resNotes, !!g.notes);
        tbx_resInitial.setValue(scwin.initials(g.fullName));
        if (g.photoUrl) { grp_resPhoto.setStyle("background-image", "url(\"" + g.photoUrl + "\")"); grp_resPhoto.addClass("has-image"); }
        else { grp_resPhoto.setStyle("background-image", "none"); grp_resPhoto.removeClass("has-image"); }
    }
    var extra = "";
    if (d.previousCheckIn) extra = "Đã check-in lúc " + scwin.fmtDateTime(d.previousCheckIn.checkInTime) + (d.previousCheckIn.checkInByName ? " bởi " + d.previousCheckIn.checkInByName : "") + ".";
    if (d.guestEvent) extra = "Khách thuộc sự kiện " + d.guestEvent.eventCode + " - " + d.guestEvent.eventName + ". Hướng dẫn khách tới đúng khu vực.";
    if (d.result === "EVENT_NOT_ACTIVE") extra = "Chuyển sự kiện sang trạng thái Đang diễn ra ở màn Sự kiện rồi quét lại.";
    if (d.result === "INVALID_QR" && g) extra = "Mã QR này đã bị thay bằng mã mới. In lại thẻ tên cho khách.";
    tbx_resExtra.setValue(extra);
    scwin.show(tbx_resExtra, !!extra);

    var canPrint = !!g && scwin.can("PRINT_BADGE") && (d.result === "SUCCESS" || d.result === "ALREADY_CHECKED_IN" || d.result === "INVALID_QR");
    scwin.show(btn_resPrint, canPrint);
    if (canPrint) {
        btn_resPrint.setValue(d.autoPrint && d.autoPrint.alreadyPrinted ? "In lại thẻ tên" : "In thẻ tên");
        scwin.resGuest = g;
    }
    clearTimeout(scwin.timers.stale);
    scwin.timers.stale = setTimeout(function () { grp_result.addClass("is-stale"); }, 9000);
};
scwin.resetResult = function () {
    ["ok", "warn", "err", "stale"].forEach(function (k) { grp_result.removeClass("is-" + k); });
    grp_result.addClass("is-idle");
    tbx_resTitle.setValue("Sẵn sàng quét");
    tbx_resMsg.setValue("Kết quả check-in hiển thị tại đây.");
    tbx_resTime.setValue("");
    scwin.show(grp_resGuest, false);
    scwin.show(tbx_resExtra, false);
    if (typeof btn_resPrint !== "undefined") scwin.show(btn_resPrint, false);
};
scwin.initials = function (n) {
    var w = scwin.trim(n).split(/\s+/).filter(function (x) { return !!x; });
    return w.length ? (w[0].charAt(0) + (w.length > 1 ? w[w.length - 1].charAt(0) : "")).toUpperCase() : "?";
};

/* ---------- Âm thanh & rung ---------- */
scwin.feedback = function (kind) {
    scwin.beep(kind);
    if (scwin.prefs.vibrate && navigator.vibrate) navigator.vibrate(kind === "ok" ? 90 : kind === "warn" ? [70, 60, 70] : [220, 80, 220]);
};
scwin.beep = function (kind) {
    if (!scwin.prefs.sound) return;
    try {
        var C = window.AudioContext || window.webkitAudioContext;
        if (!C) return;
        scwin.ac = scwin.ac || new C();
        var ac = scwin.ac, t0 = ac.currentTime;
        var seq = kind === "ok" ? [[880, 0, 0.12], [1320, 0.12, 0.1]] : kind === "warn" ? [[660, 0, 0.12], [660, 0.2, 0.12]] : [[200, 0, 0.4]];
        seq.forEach(function (s) {
            var o = ac.createOscillator(), g = ac.createGain();
            o.type = kind === "err" ? "square" : "sine";
            o.frequency.value = s[0];
            g.gain.setValueAtTime(0.0001, t0 + s[1]);
            g.gain.exponentialRampToValueAtTime(0.25, t0 + s[1] + 0.01);
            g.gain.exponentialRampToValueAtTime(0.0001, t0 + s[1] + s[2]);
            o.connect(g); g.connect(ac.destination);
            o.start(t0 + s[1]); o.stop(t0 + s[1] + s[2] + 0.02);
        });
    } catch (e) { }
};

/* ---------- In thẻ tên ---------- */
scwin.printBadge = function (guestId, name, auto) {
    if (auto) { tbx_resExtra.setValue("Đang in thẻ tên…"); scwin.show(tbx_resExtra, true); }
    btn_resPrint.addClass("is-busy");
    return scwin.xhr("POST", scwin.PRINT_API + "/quick", { body: { guestId: Number(guestId), printType: "NAMECARD", printerName: scwin.deviceInfo() || null }, responseType: "blob" })
        .then(function (r) {
            scwin.printBlob(r.blob);
            if (auto) tbx_resExtra.setValue("Đã gửi thẻ tên tới máy in.");
            scwin.toast("Đã gửi thẻ tên của " + name + " tới hộp thoại in.", "success");
        }).catch(function (err) { scwin.toast("Không in được thẻ: " + err.message, "error"); })
        .then(function () { btn_resPrint.removeClass("is-busy"); });
};
scwin.btn_resPrint_onclick = function () { if (scwin.resGuest) scwin.printBadge(scwin.resGuest.guestId, scwin.resGuest.fullName, false); };

/* =====================================================================
 * ẢNH QR
 * ===================================================================== */
scwin.initUpload = function () {
    var inp = document.createElement("input");
    inp.type = "file"; inp.accept = "image/png,image/jpeg"; inp.className = "sc-native-file";
    inp.addEventListener("change", function () { var f = inp.files && inp.files[0]; inp.value = ""; if (f) scwin.uploadImage(f); });
    document.body.appendChild(inp);
    scwin.fileInput = inp;
    var el = scwin.domOf(grp_upDrop);
    if (!el) return;
    el.addEventListener("dragover", function (e) { e.preventDefault(); grp_upDrop.addClass("is-dragover"); });
    el.addEventListener("dragleave", function () { grp_upDrop.removeClass("is-dragover"); });
    el.addEventListener("drop", function (e) { e.preventDefault(); grp_upDrop.removeClass("is-dragover"); var f = e.dataTransfer.files[0]; if (f) scwin.uploadImage(f); });
};
scwin.grp_upDrop_onclick = function () { if (scwin.fileInput) scwin.fileInput.click(); };
scwin.uploadImage = function (f) {
    if (!/^image\/(png|jpe?g)$/.test(f.type)) { scwin.toast("Chỉ nhận ảnh PNG hoặc JPG.", "warning"); return; }
    if (f.size > 5 * 1024 * 1024) { scwin.toast("Ảnh nặng " + scwin.fmtSize(f.size) + ", tối đa 5 MB.", "warning"); return; }
    if (!dma_scan.get("eventId")) { scwin.toast("Chọn sự kiện trước khi quét.", "warning"); return; }
    var url = URL.createObjectURL(f);
    grp_upDrop.setStyle("background-image", "url(\"" + url + "\")");
    grp_upDrop.addClass("has-image");
    tbx_upStatus.setValue("Đang đọc mã QR trong " + f.name + "…");
    var fd = new FormData();
    fd.append("eventId", dma_scan.get("eventId"));
    fd.append("file", f);
    fd.append("deviceInfo", scwin.deviceInfo());
    scwin.busy = true;
    grp_result.addClass("is-loading");
    scwin.xhr("POST", scwin.CHECKIN_API + "/scan-image", { body: fd })
        .then(scwin.handleResult, scwin.handleScanError)
        .then(function () {
            scwin.busy = false; grp_result.removeClass("is-loading");
            tbx_upStatus.setValue("Bấm hoặc kéo thả ảnh khác để quét tiếp.");
            setTimeout(function () { URL.revokeObjectURL(url); }, 3000);
        });
};

/* =====================================================================
 * NHẬP TAY: MÃ CHECK-IN HOẶC TÌM KHÁCH
 * ===================================================================== */
scwin.ibx_manualCode_onkeyup = function (e) { if (e && e.keyCode === 13) scwin.btn_manualSubmit_onclick(); };
scwin.btn_manualSubmit_onclick = function () {
    var v = scwin.trim(ibx_manualCode.getValue());
    if (!v) { scwin.toast("Nhập mã check-in 32 ký tự hoặc dán nội dung QR.", "warning"); return; }
    scwin.submitScan(v, null).then(function () { ibx_manualCode.setValue(""); dma_scan.set("manualCode", ""); });
};

scwin.ibx_guestSearch_onkeyup = function (e) {
    clearTimeout(scwin.timers.search);
    scwin.timers.search = setTimeout(scwin.searchGuests, (e && e.keyCode === 13) ? 0 : 350);
};
scwin.searchGuests = function () {
    var term = scwin.trim(ibx_guestSearch.getValue()), eventId = dma_scan.get("eventId");
    if (!term || !eventId) { dlt_found.setJSON([]); scwin.fitGrid(grd_found, 0); scwin.show(grp_foundEmpty, false); return; }
    scwin.callApi("sbm_guestSearch", { url: scwin.GUEST_API + "?" + scwin.buildQuery({ eventId: eventId, keyword: term, size: 10, sort: "fullName,asc" }) }).then(function (page) {
        if (scwin.trim(ibx_guestSearch.getValue()) !== term) return;
        var list = (page && page.content) || [];
        dlt_found.setJSON(list.map(function (g) {
            return { guestId: String(g.guestId), fullName: g.fullName, contact: g.email || g.phone || "", company: g.company || "",
                     tableNumber: g.tableNumber || "", statusCode: g.statusCode, checkedIn: g.checkedIn ? "1" : "0", act: "" };
        }));
        for (var i = 0; i < list.length; i++) { try { grd_found.setCellClass(i, "act", list[i].checkedIn ? "sc-act--done" : "sc-act"); } catch (e) { } }
        scwin.fitGrid(grd_found, list.length, 50);
        tbx_foundEmpty.setValue("Không tìm thấy khách khớp “" + term + "” trong sự kiện.");
        scwin.show(grp_foundEmpty, !list.length);
    }).catch(function (err) { scwin.toast(err.message, "error"); });
};
scwin.gfAct = function (v, f, i) { var r = dlt_found.getRowJSON(i) || {}; return r.checkedIn === "1" ? "Đã check-in" : "Check-in"; };
scwin.gfDash = function (v) { return scwin.dash(v); };
scwin.grd_found_oncellclick = function (rowIndex) {
    var r = dlt_found.getRowJSON(rowIndex);
    if (!r || !r.guestId || scwin.busy) return;
    var eventId = dma_scan.get("eventId");
    scwin.busy = true;
    grp_result.addClass("is-loading");
    var note = scwin.trim(ibx_manualNote.getValue());
    scwin.callApi("sbm_manual", { url: scwin.CHECKIN_API + "/manual", body: { eventId: Number(eventId), guestId: Number(r.guestId), note: note || null, deviceInfo: scwin.deviceInfo() } })
        .then(scwin.handleResult, scwin.handleScanError)
        .then(function () { scwin.busy = false; grp_result.removeClass("is-loading"); scwin.searchGuests(); });
};

/* =====================================================================
 * RECENT SCANS
 * ===================================================================== */
scwin.loadLogs = function (silent) {
    var eventId = dma_scan.get("eventId");
    if (!eventId) return;
    if (!silent) grp_logsWrap.addClass("is-loading");
    var q = { size: 10, result: sbx_logFilter.getValue() || "" };
    scwin.callApi("sbm_logs", { url: scwin.CHECKIN_API + "/events/" + eventId + "/logs?" + scwin.buildQuery(q) }).then(function (page) {
        if (dma_scan.get("eventId") !== eventId) return;
        var list = (page && page.content) || [];
        dlt_logs.setJSON(list);
        for (var i = 0; i < list.length; i++) {
            try { grd_logs.setCellClass(i, "result", "sc-res sc-res--" + (scwin.isTrue(list[i].cancelled) ? "CANCELLED" : list[i].result)); } catch (e) { }
        }
        scwin.fitGrid(grd_logs, list.length, 46);
        scwin.show(grp_logsEmpty, !list.length);
    }).catch(function () { }).then(function () { grp_logsWrap.removeClass("is-loading"); });
};
scwin.sbx_logFilter_onchange = function () { scwin.loadLogs(false); };
scwin.btn_logRefresh_onclick = function () { scwin.loadLogs(false); scwin.loadEventInfo(); };
scwin.gfClock = function (v) { return v ? scwin.fmtClock(v) : "—"; };
scwin.gfGuestName = function (v) { return v || "Không xác định"; };
scwin.gfResult = function (v, f, i) { var r = dlt_logs.getRowJSON(i) || {}; return "● " + (scwin.RESULT_VN[v] || v) + (scwin.isTrue(r.cancelled) ? " (đã hủy)" : ""); };
scwin.gfMethod = function (v) { return scwin.METHOD_VN[v] || v || "—"; };

/* =====================================================================
 * PHÍM TẮT & MÁY QUÉT CẦM TAY (gõ phím rất nhanh rồi Enter)
 * ===================================================================== */
scwin.onGlobalKeydown = function (e) {
    var tag = (e.target && e.target.tagName || "").toLowerCase();
    if (tag === "input" || tag === "textarea") return;
    var now = Date.now();
    if (e.key === "Enter") {
        var code = scwin.wedge.buf;
        scwin.wedge.buf = "";
        if (code.length >= 20) { e.preventDefault(); scwin.onDecoded(code, "QR_CAMERA"); }
        return;
    }
    if (e.key && e.key.length === 1) {
        if (now - scwin.wedge.at > 80) scwin.wedge.buf = "";
        scwin.wedge.buf += e.key;
        scwin.wedge.at = now;
    }
};

/* Handler gắn trong xf:submission (ev:submitdone / ev:submiterror) */
scwin.sbm_lookups_submitdone = function (e) { scwin.onSbmDone("sbm_lookups", e); };
scwin.sbm_lookups_submiterror = function (e) { scwin.onSbmError("sbm_lookups", e); };
scwin.sbm_eventInfo_submitdone = function (e) { scwin.onSbmDone("sbm_eventInfo", e); };
scwin.sbm_eventInfo_submiterror = function (e) { scwin.onSbmError("sbm_eventInfo", e); };
scwin.sbm_scan_submitdone = function (e) { scwin.onSbmDone("sbm_scan", e); };
scwin.sbm_scan_submiterror = function (e) { scwin.onSbmError("sbm_scan", e); };
scwin.sbm_manual_submitdone = function (e) { scwin.onSbmDone("sbm_manual", e); };
scwin.sbm_manual_submiterror = function (e) { scwin.onSbmError("sbm_manual", e); };
scwin.sbm_logs_submitdone = function (e) { scwin.onSbmDone("sbm_logs", e); };
scwin.sbm_logs_submiterror = function (e) { scwin.onSbmError("sbm_logs", e); };
scwin.sbm_guestSearch_submitdone = function (e) { scwin.onSbmDone("sbm_guestSearch", e); };
scwin.sbm_guestSearch_submiterror = function (e) { scwin.onSbmError("sbm_guestSearch", e); };
